tool_input.command:
$tmp = Join-Path $env:TEMP 'ov_align_check.py'
@'
# -*- coding: utf-8 -*-
import sqlite3, json, csv, sys, os
sys.stdout.reconfigure(encoding="utf-8")
P = r"D:\repository\数据湖\分析产出"
s = open(os.path.join(P, "持仓面板", "config.js"), encoding="utf-8").read()
s = s.split("window.PANEL_CONFIG =", 1)[1].strip().rstrip(";")
cfg = json.loads(s)
print("[config.js] meta=", cfg["meta"])
print("[config.js] targets=%d margin.targetYld=%s" % (len(cfg["targets"]), cfg["margin"]["targetYld"]))
for t in cfg["targets"]:
    print("   %s %-6s w=%-6s yld=%-6s p2=%s o2=%s held=%s" % (t["symbol"], t["name"], t["w"], t["yld"], t.get("payout2y"), t.get("ocfd2y"), t.get("held")))
rows = list(csv.DictReader(open(os.path.join(P, "打新底仓_最终8只组合_v2.csv"), encoding="utf-8-sig")))
mm = {r["sym"]: r for r in rows}
print("[最终8只组合.csv] rows=%d" % len(rows))
diffs = []
for t in cfg["targets"]:
    if t["w"] > 0:
        r = mm.get(t["symbol"])
        if not r:
            diffs.append("%s 不在组合CSV" % t["symbol"]); continue
        for a, b in [("w","w60"),("yld","yld"),("pay","pay"),("ocfd","ocfd"),("vwap60","vwap60"),("ref_px","px"),("vol","vol")]:
            try:
                if abs(float(t[a]) - float(r[b])) > 0.011: diffs.append("%s %s: js=%s csv=%s" % (t["symbol"], a, t[a], r[b]))
            except Exception as e: diffs.append("%s %s parse:%s" % (t["symbol"], a, e))
        for k in ("payout2y","ocfd2y"):
            if t.get(k) and r.get(k):
                a=t[k]; b=json.loads(r[k])
                if any(abs(x-y)>0.011 for x,y in zip(a,b)): diffs.append("%s %s: js=%s csv=%s" % (t["symbol"],k,a,b))
print("[逐值对比] 差异:", diffs if diffs else "无（8只全字段一致）")
c = sqlite3.connect(os.path.join(P, "持仓面板", "holding.sqlite"))
tables = [r[0] for r in c.execute("select name from sqlite_master where type=\"table\"")]
print("[holding.sqlite] tables=", tables)
for t in tables:
    cols = [r[1] for r in c.execute('pragma table_info("%s")' % t)]
    for col in cols:
        try:
            q = f'select "{col}" from "{t}" where cast("{col}" as text) like ? or cast("{col}" as text) like ?'
            for (v,) in c.execute(q, ("%targetYld%", "%targets%")).fetchall():
                print("[库内配置] table=%s col=%s len=%s" % (t, col, len(str(v))))
                try: d = json.loads(v)
                except Exception as e: print("   非JSON:", e, str(v)[:200]); continue
                if isinstance(d, dict) and "targets" in d:
                    print("   库内 targets=%d meta=%s" % (len(d["targets"]), d.get("meta")))
                    for x in d["targets"]:
                        print("      %s %-6s w=%-6s yld=%-6s gov=%s p2=%s o2=%s held=%s" % (x.get("symbol"), x.get("name"), x.get("w"), x.get("yld"), x.get("governance"), x.get("payout2y"), x.get("ocfd2y"), x.get("held")))
                    print("   库内 margin.targetYld=", (d.get("margin") or {}).get("targetYld"))
                    print("   库内其他键=", [k for k in d.keys()])
        except Exception as e: pass
c.close()
'@ | Set-Content -Path $tmp -Encoding UTF8
python $tmp
Write-Output "--- tmp: $tmp ---"
